mapper.select:
SELECT l.*, m.material_name, m.spec as specification, b.batch_no, w.node_name as warehouse_name FROM spd_label l LEFT JOIN spd_material m ON l.material_id = m.material_id LEFT JOIN spd_material_batch b ON l.batch_id = b.batch_id LEFT JOIN spd_org_node w ON l.warehouse_id = w.node_id WHERE l.del_flag = #{delFlag}
AND l.label_code LIKE CONCAT('%', #{query.labelCode}, '%')
AND l.material_id = #{query.materialId}
AND m.material_name LIKE CONCAT('%', #{query.materialName}, '%')
AND b.batch_no = #{query.batchNo}
AND l.warehouse_id = #{query.warehouseId}
AND l.label_status = #{query.labelStatus}
ORDER BY l.create_time DESC
